import * as rental from "host/rental";
import * as organizer from "host/organizer";
import * as strings from "std/string";

function lowercase(value: string): string {
    let upper: string = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let lower: string = "abcdefghijklmnopqrstuvwxyz";
    let result: string = "";
    for (let character: string of value) {
        let converted: string = character;
        for (let index: int = 0; index < 26; index = index + 1) {
            if (character === strings.substring(upper, index, index + 1)) {
                converted = strings.substring(lower, index, index + 1);
            }
        }
        result = result + converted;
    }
    return result;
}

function integerText(value: int): string {
    if (value === 0) {
        return "0";
    }
    let digits: string = "0123456789";
    let result: string = "";
    for (let remaining: int = value; remaining > 0; remaining = remaining / 10) {
        let digit: int = remaining % 10;
        result = strings.substring(digits, digit, digit + 1) + result;
    }
    return result;
}

function euroPrice(cents: int): string {
    let whole: int = cents / 100;
    let fraction: int = cents % 100;
    let fractionText: string = integerText(fraction);
    if (fraction < 10) {
        fractionText = "0" + fractionText;
    }
    return "€" + integerText(whole) + "." + fractionText;
}

function copyOptions(options: Equipment[], selectedId: string): Equipment[] {
    let copied: Equipment[] = [];
    for (let item: Equipment of options) {
        let copy: Equipment = {
            id: item.id,
            title: item.title,
            detail: item.detail,
            totalCents: item.totalCents,
            price: item.price,
            meta: item.meta,
            enabled: item.enabled,
            selected: item.id === selectedId
        };
        copied[copied.length] = copy;
    }
    return copied;
}

function copyState(state: State): State {
    return {
        quantity: state.quantity,
        budgetCents: state.budgetCents,
        periodStart: state.periodStart,
        periodEnd: state.periodEnd,
        options: copyOptions(state.options, state.selectedId),
        selectedId: state.selectedId,
        loading: state.loading,
        staging: state.staging,
        loaded: state.loaded,
        empty: state.empty,
        loadError: state.loadError,
        stageError: state.stageError,
        prepared: state.prepared,
        reference: state.reference
    };
}

export class Equipment {
    id: string = "";
    title: string = "";
    detail: string = "";
    totalCents: int = 0;
    price: string = "";
    meta: string = "";
    enabled: boolean = true;
    selected: boolean = false;
}

export class State {
    quantity: int = 2;
    budgetCents: int = 1800;
    periodStart: string = "2026-10-10T16:00:00Z";
    periodEnd: string = "2026-10-10T22:00:00Z";
    options: Equipment[] = [];
    selectedId: string = "";
    loading: boolean = false;
    staging: boolean = false;
    loaded: boolean = false;
    empty: boolean = false;
    loadError: string = "";
    stageError: string = "";
    prepared: boolean = false;
    reference: string = "";
}

export class LoadOptions {}

export class OptionsLoaded {
    options: Equipment[] = [];
    error: string = "";
}

export class SelectOption {
    value: string = "";
}

export class PrepareReview {}

export class ReviewPrepared {
    staged: boolean = false;
    reference: string = "";
    error: string = "";
}

export function main(): null {
    return null;
}

export function initialState(): State {
    return {};
}

// @ui-update
export function startLoading(state: State, action: LoadOptions): State {
    if (state.loading || state.staging) {
        return copyState(state);
    }
    return {
        quantity: state.quantity,
        budgetCents: state.budgetCents,
        periodStart: state.periodStart,
        periodEnd: state.periodEnd,
        options: copyOptions(state.options, state.selectedId),
        selectedId: state.selectedId,
        loading: true,
        staging: false,
        loaded: state.loaded,
        empty: false,
        loadError: "",
        stageError: "",
        prepared: false,
        reference: ""
    };
}

// @ui-effect
export async function run(state: State, action: LoadOptions): OptionsLoaded {
    try {
        let records: table[] = await rental.equipment(state.periodStart, state.periodEnd);
        let options: Equipment[] = [];
        for (let record: table of records) {
            let id: string = record.id;
            let title: string = record.name;
            let specification: string = record.specification;
            let cents: int = record.cents;
            let available: int = record.available;
            let searchable: string = lowercase(title + " " + specification);
            let matches: boolean = strings.contains(searchable, "boom") && strings.contains(searchable, "stand");
            if (matches && available >= state.quantity && cents >= 0) {
                if (state.quantity > 0 && cents <= state.budgetCents / state.quantity) {
                    let totalCents: int = cents * state.quantity;
                    let option: Equipment = {
                        id: id,
                        title: title,
                        detail: specification,
                        totalCents: totalCents,
                        price: euroPrice(totalCents),
                        meta: "Total for " + integerText(state.quantity) + " units",
                        enabled: true,
                        selected: id === state.selectedId
                    };
                    options[options.length] = option;
                }
            }
        }
        return { options: options, error: "" };
    } catch (e) {
        return { options: [], error: "Could not load options: " + e.message };
    }
}

// @ui-update
export function finishLoading(state: State, action: OptionsLoaded): State {
    if (action.error !== "") {
        return {
            quantity: state.quantity,
            budgetCents: state.budgetCents,
            periodStart: state.periodStart,
            periodEnd: state.periodEnd,
            options: copyOptions(state.options, state.selectedId),
            selectedId: state.selectedId,
            loading: false,
            staging: state.staging,
            loaded: state.loaded,
            empty: false,
            loadError: action.error,
            stageError: state.stageError,
            prepared: state.prepared,
            reference: state.reference
        };
    }
    let retainedId: string = "";
    for (let item: Equipment of action.options) {
        if (item.id === state.selectedId) {
            retainedId = item.id;
        }
    }
    let options: Equipment[] = copyOptions(action.options, retainedId);
    return {
        quantity: state.quantity,
        budgetCents: state.budgetCents,
        periodStart: state.periodStart,
        periodEnd: state.periodEnd,
        options: options,
        selectedId: retainedId,
        loading: false,
        staging: state.staging,
        loaded: true,
        empty: options.length === 0,
        loadError: "",
        stageError: "",
        prepared: false,
        reference: ""
    };
}

// @ui-update
export function selectOption(state: State, action: SelectOption): State {
    if (state.loading || state.staging) {
        return copyState(state);
    }
    let selectedId: string = state.selectedId;
    for (let item: Equipment of state.options) {
        if (item.id === action.value && item.enabled) {
            selectedId = action.value;
        }
    }
    let prepared: boolean = state.prepared;
    let reference: string = state.reference;
    let stageError: string = state.stageError;
    if (selectedId !== state.selectedId) {
        prepared = false;
        reference = "";
        stageError = "";
    }
    return {
        quantity: state.quantity,
        budgetCents: state.budgetCents,
        periodStart: state.periodStart,
        periodEnd: state.periodEnd,
        options: copyOptions(state.options, selectedId),
        selectedId: selectedId,
        loading: state.loading,
        staging: state.staging,
        loaded: state.loaded,
        empty: state.empty,
        loadError: state.loadError,
        stageError: stageError,
        prepared: prepared,
        reference: reference
    };
}

// @ui-update
export function startPreparation(state: State, action: PrepareReview): State {
    if (state.loading || state.staging) {
        return copyState(state);
    }
    return {
        quantity: state.quantity,
        budgetCents: state.budgetCents,
        periodStart: state.periodStart,
        periodEnd: state.periodEnd,
        options: copyOptions(state.options, state.selectedId),
        selectedId: state.selectedId,
        loading: state.loading,
        staging: true,
        loaded: state.loaded,
        empty: state.empty,
        loadError: state.loadError,
        stageError: "",
        prepared: false,
        reference: ""
    };
}

// @ui-effect
export async function stageSelection(state: State, action: PrepareReview): ReviewPrepared {
    try {
        let selected: Equipment | null = null;
        for (let item: Equipment of state.options) {
            if (item.id === state.selectedId && item.enabled) {
                selected = item;
            }
        }
        if (selected !== null) {
            let title: string = selected.title;
            let id: string = selected.id;
            let totalCents: int = selected.totalCents;
            let detail: string = "Item " + id + ":" + integerText(state.quantity) + "; from " + state.periodStart + "; until " + state.periodEnd;
            let price: string = euroPrice(totalCents);
            let result: table = await organizer.stage("rental", "host/rental", title, detail, price, state.periodEnd);
            let staged: boolean = result.staged;
            let reference: string = result.reference;
            if (!staged) {
                return { staged: false, reference: reference, error: "The selection was not prepared. Please retry." };
            }
            return { staged: true, reference: reference, error: "" };
        } else {
            return { staged: false, reference: "", error: "Select a qualifying option before preparing it for review." };
        }
    } catch (e) {
        return { staged: false, reference: "", error: "Could not prepare for review: " + e.message };
    }
}

// @ui-update
export function finishPreparation(state: State, action: ReviewPrepared): State {
    return {
        quantity: state.quantity,
        budgetCents: state.budgetCents,
        periodStart: state.periodStart,
        periodEnd: state.periodEnd,
        options: copyOptions(state.options, state.selectedId),
        selectedId: state.selectedId,
        loading: state.loading,
        staging: false,
        loaded: state.loaded,
        empty: state.empty,
        loadError: state.loadError,
        stageError: action.error,
        prepared: action.staged,
        reference: action.reference
    };
}

