import * as app from "./experience";
import * as ui from "./platform.dealui-pack";

// @ui-root
export view RentalShortlist(state: app.State): View {
    ui.Column() {
        ui.Hero(value: "Boom stand rental shortlist")
        ui.Text(value: "Adjustable boom with clip adapter. Quantity: 2. Total budget: €18.00.")
        ui.Text(value: state.periodStart)
        ui.Text(value: state.periodEnd)
        ui.Notice(text: "Catalogue matches require both boom and stand, enough available units, and a total price within budget. Preparation is for native review only; it does not reserve equipment.", tone: "info")
        When(state.loading) {
            ui.Progress(label: "Loading qualifying options")
        } Else {
            When(state.staging) {
                ui.Progress(label: "Preparing selection for native review")
                ForEach(state.options, item: app.Equipment, key: item.id) {
                    When(item.selected) {
                        ui.Item(value: item.id, title: item.title, detail: item.detail, meta: item.meta, trailing: item.price) {
                            ui.Text(value: "Selected")
                        }
                    }
                }
            } Else {
                When(state.loadError !== "") {
                    ui.Failure(text: state.loadError, onRetry: action app.LoadOptions {}, accessibilityLabel: "Retry Load options")
                } Else {
                    When(state.loaded) {
                        When(state.empty) {
                            ui.Text(value: "No options match both boom and stand with at least 2 available units and a total price of €18.00 or less.")
                            ui.Button(text: "Load options", onClick: action app.LoadOptions {}, accessibilityLabel: "Load options")
                        } Else {
                            ui.Section(title: "Qualifying options", summary: "Prices are totals for both units. Select one option to prepare it for native review.") {
                                ForEach(state.options, item: app.Equipment, key: item.id) {
                                    ui.Option(value: item.id, title: item.title, detail: item.detail, price: item.price, meta: item.meta, enabled: item.enabled, selected: item.selected, onSelect: action app.SelectOption { value: payload }, accessibilityLabel: item.title) {
                                        When(item.selected) {
                                            ui.Text(value: "Selected")
                                        }
                                    }
                                }
                            }
                            When(state.prepared) {
                                ui.Notice(text: "Prepared for native review", tone: "info")
                                ui.Text(value: "Your selection is retained. No reservation has been made.")
                                ui.Button(text: "Load options", onClick: action app.LoadOptions {}, accessibilityLabel: "Load options")
                            } Else {
                                When(state.stageError !== "") {
                                    ui.Failure(text: state.stageError, onRetry: action app.PrepareReview {}, accessibilityLabel: "Retry Prepare for review")
                                } Else {
                                    When(state.selectedId !== "") {
                                        ui.Button(text: "Prepare for review", onClick: action app.PrepareReview {}, accessibilityLabel: "Prepare selected rental for native review")
                                    } Else {
                                        ui.Text(value: "Select an option to prepare it for review.")
                                        ui.Button(text: "Load options", onClick: action app.LoadOptions {}, accessibilityLabel: "Load options")
                                    }
                                }
                            }
                        }
                    } Else {
                        ui.Text(value: "Load the catalogue to find qualifying rental options. No catalogue reads occur before you press Load options.")
                        ui.Button(text: "Load options", onClick: action app.LoadOptions {}, accessibilityLabel: "Load options")
                    }
                }
            }
        }
    }
}
